<?php
namespace App\Filament\Widgets; use App\Models\DisplayStatus; use App\Models\Layout; use App\Models\MediaAsset; use Filament\Widgets\StatsOverviewWidget; use Filament\Widgets\StatsOverviewWidget\Stat;
class SystemStatus extends StatsOverviewWidget {protected function getStats():array{$d=DisplayStatus::where('display_key','main-display')->first();$online=$d?->last_seen_at?->gt(now()->subSeconds(15));$used=MediaAsset::sum('file_size');return[Stat::make('Reproductor',$online?($d->state==='online'?'En línea':$d->state):'Sin conexión')->color($online?'success':'danger'),Stat::make('Publicación activa',Layout::where('state','published')->max('version')?:'Sin publicar'),Stat::make('Contenidos',MediaAsset::count())->description(number_format($used/1073741824,2).' GB utilizados')];}}
